CREATE SET TABLE MDP01_META.META_ETL_TEST_RESULT ,FALLBACK ,     NO BEFORE JOURNAL,     NO AFTER JOURNAL,     CHECKSUM = DEFAULT,     DEFAULT MERGEBLOCKRATIO,     MAP = TD_MAP1     (      test_result_id INTEGER NOT NULL,      test_id INTEGER NOT NULL,      run_id INTEGER NOT NULL,      test_status VARCHAR(20) CHARACTER SET LATIN NOT CASESPECIFIC NOT NULL,      rows_tested DECIMAL(18,0),      rows_failed DECIMAL(18,0),      failure_rate DECIMAL(5,2),      failure_sample CLOB(16777216) CHARACTER SET UNICODE,      execution_time_ms INTEGER,      test_timestamp TIMESTAMP(6) NOT NULL)PRIMARY INDEX ( test_result_id )INDEX ( test_id ,test_timestamp )INDEX ( run_id );